{
    "id": "vuln-nocodb-079e3abe",
    "message": "Missing escapeFormulae option in Papaparse.unparse() call. This vulnerability allows CSV formula injection attacks where malicious data entered into CSV cells can execute arbitrary commands when opened in spreadsheet applications like Excel or Google Sheets. The fix is to add { escapeFormulae: true } as the second argument to Papaparse.unparse().",
    "severity": "ERROR",
    "languages": ["typescript"],
    "metadata": {
        "category": "security",
        "cwe": "CWE-1235",
        "owasp": "OWASP-A03:2021"
    },
    "pattern_either": [
        "const data = Papaparse.unparse({ ... });",
        "const data = Papaparse.unparse(...);"
    ],
    "pattern_not": [
        "const data = Papaparse.unparse(..., { escapeFormulae: true });"
    ]
}

